CREATE TABLE public.website_services (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length(slug) <= 80),
  icon text NOT NULL DEFAULT 'Smile' CHECK (char_length(icon) <= 40),
  name_en text NOT NULL CHECK (char_length(name_en) BETWEEN 1 AND 160),
  name_ta text CHECK (name_ta IS NULL OR char_length(name_ta) <= 160),
  short_description_en text NOT NULL DEFAULT '' CHECK (char_length(short_description_en) <= 500),
  short_description_ta text CHECK (short_description_ta IS NULL OR char_length(short_description_ta) <= 500),
  about_en text NOT NULL DEFAULT '' CHECK (char_length(about_en) <= 10000),
  about_ta text CHECK (about_ta IS NULL OR char_length(about_ta) <= 10000),
  highlights_en jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(highlights_en) = 'array'),
  highlights_ta jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(highlights_ta) = 'array'),
  faqs jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(faqs) = 'array'),
  image_url text CHECK (image_url IS NULL OR (image_url ~ '^https://' AND char_length(image_url) <= 2048)),
  price_label_en text CHECK (price_label_en IS NULL OR char_length(price_label_en) <= 120),
  price_label_ta text CHECK (price_label_ta IS NULL OR char_length(price_label_ta) <= 120),
  sort_order integer NOT NULL DEFAULT 100 CHECK (sort_order BETWEEN 0 AND 10000),
  is_published boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.website_services TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_services TO authenticated;
GRANT ALL ON public.website_services TO service_role;
ALTER TABLE public.website_services ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published services are public" ON public.website_services FOR SELECT TO public USING (is_published = true);
CREATE POLICY "Staff manage website services" ON public.website_services FOR ALL TO authenticated USING ((select public.is_staff())) WITH CHECK ((select public.is_staff()));
CREATE INDEX website_services_public_order_idx ON public.website_services (is_published, sort_order, slug);
CREATE TRIGGER update_website_services_updated_at BEFORE UPDATE ON public.website_services FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE public.website_homepage (
  id text PRIMARY KEY DEFAULT 'main' CHECK (id = 'main'),
  hero_title_en text NOT NULL CHECK (char_length(hero_title_en) BETWEEN 1 AND 240),
  hero_title_ta text CHECK (hero_title_ta IS NULL OR char_length(hero_title_ta) <= 240),
  hero_subtitle_en text NOT NULL DEFAULT '' CHECK (char_length(hero_subtitle_en) <= 1000),
  hero_subtitle_ta text CHECK (hero_subtitle_ta IS NULL OR char_length(hero_subtitle_ta) <= 1000),
  hero_image_url text CHECK (hero_image_url IS NULL OR (hero_image_url ~ '^https://' AND char_length(hero_image_url) <= 2048)),
  about_title_en text NOT NULL CHECK (char_length(about_title_en) BETWEEN 1 AND 240),
  about_title_ta text CHECK (about_title_ta IS NULL OR char_length(about_title_ta) <= 240),
  about_body_en text NOT NULL DEFAULT '' CHECK (char_length(about_body_en) <= 12000),
  about_body_ta text CHECK (about_body_ta IS NULL OR char_length(about_body_ta) <= 12000),
  about_image_url text CHECK (about_image_url IS NULL OR (about_image_url ~ '^https://' AND char_length(about_image_url) <= 2048)),
  section_order jsonb NOT NULL DEFAULT '["home","services","about","home-visit","testimonials","appointment","contact"]'::jsonb CHECK (jsonb_typeof(section_order) = 'array'),
  hidden_sections jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(hidden_sections) = 'array'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.website_homepage TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_homepage TO authenticated;
GRANT ALL ON public.website_homepage TO service_role;
ALTER TABLE public.website_homepage ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Homepage content is public" ON public.website_homepage FOR SELECT TO public USING (true);
CREATE POLICY "Staff manage homepage content" ON public.website_homepage FOR ALL TO authenticated USING ((select public.is_staff())) WITH CHECK ((select public.is_staff()));
CREATE TRIGGER update_website_homepage_updated_at BEFORE UPDATE ON public.website_homepage FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.website_homepage (hero_title_en, hero_title_ta, hero_subtitle_en, hero_subtitle_ta, about_title_en, about_title_ta, about_body_en, about_body_ta) VALUES (
  'One Stop for All Dental Solutions',
  'அனைத்து பல் சிகிச்சைகளுக்கும் ஒரே இடம்',
  'Experience advanced dental care at West Mambalam, Chennai. Led by Dr. Karthik Srinivasan.',
  'மேற்கு மாம்பலம், சென்னையில் மேம்பட்ட பல் சிகிச்சை. டாக்டர் கார்த்திக் ஸ்ரீனிவாசன் வழிநடத்துகிறார்.',
  'Meet Dr. Karthik Srinivasan',
  'டாக்டர் கார்த்திக் ஸ்ரீனிவாசனை சந்தியுங்கள்',
  'Dr. Karthik Srinivasan leads the West Mambalam branch of Tooth Haven. A BDS graduate from Sree Balaji Dental College and Hospital, Chennai (2010), registered with Tamil Nadu Dental Council (Reg. No. 20674), he brings over 13 years of experience in advanced dental care.\n\nSpecializations: Oral Implantologist, Oral Rehabilitation, Orthodontist, Aesthetic Dentist, Pedodontist, Smile Designing, Conservative Dentistry & Endodontics, Oral Surgeon and Cosmetic Dentist.',
  'டாக்டர் கார்த்திக் ஸ்ரீனிவாசன் டூத் ஹேவனின் மேற்கு மாம்பலம் கிளையை வழிநடத்துகிறார். சென்னை ஸ்ரீ பாலாஜி டென்டல் கல்லூரியில் BDS பட்டம் பெற்ற இவர், தமிழ்நாடு டென்டல் கவுன்சிலில் பதிவு செய்யப்பட்டவர் (பதிவு எண். 20674). 13 ஆண்டுகளுக்கும் மேலான அனுபவம் கொண்டவர்.'
) ON CONFLICT (id) DO NOTHING;

CREATE TABLE public.website_sections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  section_key text NOT NULL UNIQUE CHECK (section_key ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length(section_key) <= 80),
  title_en text NOT NULL CHECK (char_length(title_en) BETWEEN 1 AND 240),
  title_ta text CHECK (title_ta IS NULL OR char_length(title_ta) <= 240),
  body_en text NOT NULL DEFAULT '' CHECK (char_length(body_en) <= 12000),
  body_ta text CHECK (body_ta IS NULL OR char_length(body_ta) <= 12000),
  image_url text CHECK (image_url IS NULL OR (image_url ~ '^https://' AND char_length(image_url) <= 2048)),
  video_url text CHECK (video_url IS NULL OR (video_url ~ '^https://' AND char_length(video_url) <= 2048)),
  items jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) <= 100),
  sort_order integer NOT NULL DEFAULT 100 CHECK (sort_order BETWEEN 0 AND 10000),
  show_in_menu boolean NOT NULL DEFAULT false,
  is_published boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.website_sections TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_sections TO authenticated;
GRANT ALL ON public.website_sections TO service_role;
ALTER TABLE public.website_sections ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published sections are public" ON public.website_sections FOR SELECT TO public USING (is_published = true);
CREATE POLICY "Staff manage website sections" ON public.website_sections FOR ALL TO authenticated USING ((select public.is_staff())) WITH CHECK ((select public.is_staff()));
CREATE INDEX website_sections_public_order_idx ON public.website_sections (is_published, sort_order, section_key);
CREATE TRIGGER update_website_sections_updated_at BEFORE UPDATE ON public.website_sections FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE public.website_pages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length(slug) <= 80),
  title_en text NOT NULL CHECK (char_length(title_en) BETWEEN 1 AND 240),
  title_ta text CHECK (title_ta IS NULL OR char_length(title_ta) <= 240),
  content_en text NOT NULL DEFAULT '' CHECK (char_length(content_en) <= 30000),
  content_ta text CHECK (content_ta IS NULL OR char_length(content_ta) <= 30000),
  image_url text CHECK (image_url IS NULL OR (image_url ~ '^https://' AND char_length(image_url) <= 2048)),
  video_url text CHECK (video_url IS NULL OR (video_url ~ '^https://' AND char_length(video_url) <= 2048)),
  sort_order integer NOT NULL DEFAULT 100 CHECK (sort_order BETWEEN 0 AND 10000),
  show_in_menu boolean NOT NULL DEFAULT false,
  is_published boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.website_pages TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_pages TO authenticated;
GRANT ALL ON public.website_pages TO service_role;
ALTER TABLE public.website_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published pages are public" ON public.website_pages FOR SELECT TO public USING (is_published = true);
CREATE POLICY "Staff manage website pages" ON public.website_pages FOR ALL TO authenticated USING ((select public.is_staff())) WITH CHECK ((select public.is_staff()));
CREATE INDEX website_pages_public_order_idx ON public.website_pages (is_published, sort_order, slug);
CREATE TRIGGER update_website_pages_updated_at BEFORE UPDATE ON public.website_pages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

INSERT INTO public.website_services (slug, icon, name_en, name_ta, short_description_en, short_description_ta, about_en, about_ta, highlights_en, highlights_ta, faqs, sort_order, is_published) VALUES
('general-dentistry','Smile','General Dentistry','பொது பல் மருத்துவம்','Check-ups, consultation, scaling and polishing','பரிசோதனை, ஆலோசனை, ஸ்கேலிங் மற்றும் பாலிஷிங்','Routine dental care keeps small problems small. Our general dentistry visits include a full oral examination, digital X-rays when needed, professional scaling to remove tartar, and polishing for a smooth, stain-free finish.','வழக்கமான பல் பராமரிப்பு சிறிய பிரச்சனைகளை பெரிதாகாமல் தடுக்கிறது. முழு வாய் பரிசோதனை, தேவைப்பட்டால் டிஜிட்டல் எக்ஸ்-ரே, ஸ்கேலிங் மற்றும் பாலிஷிங் ஆகியவை அடங்கும்.','["Full oral examination", "Ultrasonic scaling & polishing", "Digital X-ray / RVG", "Preventive advice & recall reminders"]'::jsonb,'["முழு வாய் பரிசோதனை", "ஸ்கேலிங் & பாலிஷிங்", "டிஜிட்டல் எக்ஸ்-ரே / RVG", "தடுப்பு ஆலோசனை மற்றும் நினைவூட்டல்"]'::jsonb,'[{"qEn": "How often should I get a dental check-up?", "qTa": "எத்தனை முறை பரிசோதனை தேவை?", "aEn": "Once every six months for most people; every three to four months if you have gum disease, diabetes or smoke.", "aTa": "பொதுவாக ஆறு மாதங்களுக்கு ஒரு முறை; ஈறு நோய், சர்க்கரை நோய் இருந்தால் 3-4 மாதங்களுக்கு ஒரு முறை."}, {"qEn": "Does scaling loosen my teeth?", "qTa": "ஸ்கேலிங் பற்களை தளர்த்துமா?", "aEn": "No. Scaling removes hardened tartar. Teeth may feel different for a few days because the deposits holding them are gone, but gums tighten back as they heal.", "aTa": "இல்லை. ஸ்கேலிங் கடினமான படிவுகளை மட்டுமே நீக்குகிறது; ஈறுகள் குணமாகும் போது இறுக்கமாகும்."}, {"qEn": "Is the check-up painful?", "qTa": "பரிசோதனை வலிக்குமா?", "aEn": "A check-up and scaling are not painful. Mild sensitivity for a day or two is normal and settles quickly.", "aTa": "இல்லை. ஓரிரு நாட்கள் லேசான உணர்திறன் இருக்கலாம், விரைவில் சரியாகிவிடும்."}]'::jsonb,10,true),
('dental-implants','ShieldCheck','Dental Implants','பல் பொருத்துதல்','Digital dental implantology and maxillofacial implants','டிஜிட்டல் டென்டல் இம்ப்ளான்டாலஜி','An implant is a titanium root placed in the jawbone to replace a missing tooth. We plan every case on CBCT so the implant sits in safe bone, and restore it with a custom crown that matches your natural teeth.','இம்ப்ளான்ட் என்பது இழந்த பல்லுக்கு பதிலாக தாடை எலும்பில் பொருத்தப்படும் டைட்டானியம் வேர். ஒவ்வொரு சிகிச்சையும் CBCT மூலம் திட்டமிடப்படுகிறது.','["CBCT-guided planning", "Single tooth to full-arch solutions", "Immediate loading where suitable", "Custom zirconia crowns"]'::jsonb,'["CBCT வழிகாட்டுதல்", "ஒரு பல் முதல் முழு தாடை வரை", "தேவைப்பட்டால் உடனடி ஏற்றுதல்", "தனிப்பயன் ஜிர்கோனியா கிரீடம்"]'::jsonb,'[{"qEn": "How long does an implant last?", "qTa": "இம்ப்ளான்ட் எவ்வளவு காலம் நிலைக்கும்?", "aEn": "With good hygiene and regular reviews, implants routinely last 15-25 years or more.", "aTa": "நல்ல பராமரிப்புடன் 15-25 ஆண்டுகள் அல்லது அதற்கு மேல்."}, {"qEn": "Is implant surgery painful?", "qTa": "அறுவை சிகிச்சை வலிக்குமா?", "aEn": "It is done under local anaesthesia and most patients report less discomfort than an extraction.", "aTa": "மரத்துப்போகும் மருந்துடன் செய்யப்படுகிறது; பல் எடுப்பதை விட குறைவான அசௌகரியம்."}, {"qEn": "How long before I get the crown?", "qTa": "கிரீடம் எப்போது பொருத்தப்படும்?", "aEn": "Usually 3-4 months for the bone to integrate, though selected cases allow a temporary tooth the same day.", "aTa": "பொதுவாக 3-4 மாதங்கள்; சில சமயம் அன்றே தற்காலிக பல் வைக்கலாம்."}]'::jsonb,20,true),
('root-canal','HeartPulse','Root Canal','வேர் கால்வாய் சிகிச்சை','Endodontics and conservative dentistry','எண்டோடான்டிக்ஸ் மற்றும் கன்சர்வேடிவ் டென்டிஸ்ட்ரி','Root canal treatment saves a tooth whose nerve is infected. The inflamed pulp is removed, the canals are cleaned and sealed, and the tooth is protected with a crown so you can chew normally again.','நரம்பு தொற்று ஏற்பட்ட பல்லை காப்பாற்றும் சிகிச்சை. கால்வாய்கள் சுத்தம் செய்யப்பட்டு அடைக்கப்படுகின்றன, பின்னர் கிரீடம் பொருத்தப்படுகிறது.','["Single-sitting RCT where possible", "Rotary & apex locator precision", "Post-and-core build up", "Crown protection"]'::jsonb,'["ஒரே அமர்வில் சிகிச்சை", "ரோட்டரி கருவிகள்", "போஸ்ட் & கோர்", "கிரீடம் பாதுகாப்பு"]'::jsonb,'[{"qEn": "Is a root canal painful?", "qTa": "வேர் கால்வாய் சிகிச்சை வலிக்குமா?", "aEn": "The procedure itself is done under anaesthesia and is comfortable. It relieves the pain you came in with.", "aTa": "மரத்துப்போகும் மருந்துடன் செய்யப்படுவதால் வலி இருக்காது; இருந்த வலி நீங்கும்."}, {"qEn": "Do I really need a crown after?", "qTa": "கிரீடம் அவசியமா?", "aEn": "Yes. A treated tooth becomes brittle and a crown prevents it from fracturing.", "aTa": "ஆம். சிகிச்சை பெற்ற பல் உடையக்கூடியது, கிரீடம் அதை பாதுகாக்கும்."}, {"qEn": "How many visits will it take?", "qTa": "எத்தனை முறை வர வேண்டும்?", "aEn": "Most teeth are completed in one or two visits; infected teeth may need a third.", "aTa": "பொதுவாக ஒன்று அல்லது இரண்டு முறை; தொற்று இருந்தால் மூன்று."}]'::jsonb,30,true),
('orthodontics','Wrench','Orthodontics','பல் சீரமைப்பு','Braces, retainers, space maintainers and aligners','பிரேஸ்கள், ரிடெய்னர்கள், அலைனர்கள்','Crooked or crowded teeth are straightened with metal, ceramic or clear aligner systems. Treatment improves bite function and makes cleaning far easier, not just appearance.','வளைந்த அல்லது நெருக்கமான பற்களை மெட்டல், செராமிக் அல்லது தெளிவான அலைனர் மூலம் சீரமைக்கிறோம். கடி செயல்பாடும் சுத்தம் செய்வதும் எளிதாகும்.','["Metal & ceramic braces", "Clear aligners", "Space maintainers for children", "Retainers after treatment"]'::jsonb,'["மெட்டல் & செராமிக் பிரேஸ்", "தெளிவான அலைனர்கள்", "குழந்தைகளுக்கு ஸ்பேஸ் மெயின்டெய்னர்", "ரிடெய்னர்கள்"]'::jsonb,'[{"qEn": "How long does braces treatment take?", "qTa": "எவ்வளவு காலம் ஆகும்?", "aEn": "Typically 12-24 months depending on how much movement is needed.", "aTa": "பொதுவாக 12-24 மாதங்கள்."}, {"qEn": "Am I too old for braces?", "qTa": "வயதானவர்கள் செய்யலாமா?", "aEn": "No. Healthy teeth and gums matter more than age; many adults treat in their 30s and 40s.", "aTa": "ஆம். வயதை விட ஈறு ஆரோக்கியமே முக்கியம்."}, {"qEn": "Are aligners as effective as braces?", "qTa": "அலைனர்கள் பயனுள்ளதா?", "aEn": "For mild to moderate crowding, yes. Complex bites are still handled best with fixed braces.", "aTa": "லேசான பிரச்சனைகளுக்கு ஆம்; சிக்கலான நிலைகளுக்கு பிரேஸ் சிறந்தது."}]'::jsonb,40,true),
('cosmetic-dentistry','Sparkles','Cosmetic Dentistry','அழகு பல் மருத்துவம்','Teeth whitening, bleaching, veneers and smile makeovers','பற்கள் வெண்மையாக்கல், வினீர்கள், புன்னகை மாற்றம்','From professional whitening to porcelain veneers and complete smile makeovers, cosmetic treatment is planned around your face, lip line and natural tooth shade.','வெண்மையாக்கல் முதல் வினீர்கள் மற்றும் முழு புன்னகை மாற்றம் வரை, உங்கள் முகம் மற்றும் இயற்கை நிறத்திற்கு ஏற்ப திட்டமிடப்படுகிறது.','["In-office & home whitening", "Porcelain / composite veneers", "Gum contouring", "Digital smile preview"]'::jsonb,'["கிளினிக் & வீட்டு வெண்மையாக்கல்", "வினீர்கள்", "ஈறு வடிவமைப்பு", "டிஜிட்டல் புன்னகை முன்னோட்டம்"]'::jsonb,'[{"qEn": "Does whitening damage enamel?", "qTa": "வெண்மையாக்கல் பாதிப்பு தருமா?", "aEn": "Professionally supervised whitening does not damage enamel. Temporary sensitivity is common and reversible.", "aTa": "மருத்துவர் மேற்பார்வையில் செய்தால் பாதிப்பில்லை; தற்காலிக உணர்திறன் மட்டுமே."}, {"qEn": "How long do results last?", "qTa": "விளைவு எவ்வளவு காலம்?", "aEn": "Whitening lasts 1-2 years with care; veneers last 10-15 years.", "aTa": "வெண்மையாக்கல் 1-2 ஆண்டுகள்; வினீர்கள் 10-15 ஆண்டுகள்."}, {"qEn": "Will veneers look artificial?", "qTa": "வினீர்கள் செயற்கையாக தெரியுமா?", "aEn": "No. Shade, translucency and shape are matched to your natural teeth before they are bonded.", "aTa": "இல்லை. நிறமும் வடிவமும் உங்கள் இயற்கை பற்களுக்கு ஏற்ப தேர்வு செய்யப்படும்."}]'::jsonb,50,true),
('crowns-bridges','Crown','Crowns & Bridges','கிரீடங்கள் & பாலங்கள்','Ceramic crowns, zirconia, dental crowns and bridges','செராமிக் கிரீடங்கள், ஜிர்கோனியா, பாலங்கள்','Crowns rebuild a broken or root-treated tooth; bridges replace a missing tooth using the neighbouring teeth for support. We use metal-free zirconia and layered ceramics for a natural look.','கிரீடம் உடைந்த பல்லை மீட்டமைக்கிறது; பாலம் இழந்த பல்லுக்கு பதிலாக அமைகிறது. உலோகமற்ற ஜிர்கோனியா பயன்படுத்தப்படுகிறது.','["Zirconia & E-max crowns", "Metal-ceramic options", "Digital shade matching", "Trial fit before cementing"]'::jsonb,'["ஜிர்கோனியா & E-max", "மெட்டல்-செராமிக்", "டிஜிட்டல் நிற பொருத்தம்", "நிரந்தரமாக்கும் முன் சோதனை"]'::jsonb,'[{"qEn": "How long does a crown take?", "qTa": "எத்தனை நாட்கள் ஆகும்?", "aEn": "Usually two visits about a week apart; a temporary crown protects the tooth in between.", "aTa": "பொதுவாக ஒரு வாரம் இடைவெளியில் இரண்டு முறை வருகை."}, {"qEn": "Crown or bridge for a missing tooth?", "qTa": "கிரீடமா பாலமா?", "aEn": "An implant with a crown preserves neighbouring teeth; a bridge is faster but requires trimming the adjacent teeth.", "aTa": "இம்ப்ளான்ட் அருகிலுள்ள பற்களை பாதுகாக்கும்; பாலம் விரைவானது ஆனால் அருகில் உள்ள பற்களை சீவ வேண்டும்."}, {"qEn": "Can crowns stain?", "qTa": "பற்கள் நிறம் மாறுமா?", "aEn": "Ceramic crowns resist staining, but the surrounding natural teeth can darken over time.", "aTa": "செராமிக் கிரீடம் நிறம் மாறாது; இயற்கை பற்கள் மாறலாம்."}]'::jsonb,60,true),
('digital-smile-design','Zap','Digital Smile Design','டிஜிட்டல் புன்னகை வடிவமைப்பு','Computer-aided smile planning and facial esthetics','கணினி புன்னகை திட்டமிடல் மற்றும் முக அழகியல்','We photograph and scan your smile, then design the final result on screen before any treatment begins, so you can see and approve the outcome in advance.','உங்கள் புன்னகையை படமெடுத்து ஸ்கேன் செய்து, சிகிச்சை தொடங்கும் முன்பே இறுதி முடிவை திரையில் பார்த்து ஒப்புதல் அளிக்கலாம்.','["Photo & video smile analysis", "On-screen design preview", "Mock-up trial smile", "Predictable final result"]'::jsonb,'["புகைப்பட பகுப்பாய்வு", "திரையில் முன்னோட்டம்", "சோதனை புன்னகை", "நம்பகமான முடிவு"]'::jsonb,'[{"qEn": "Is the preview accurate?", "qTa": "முன்னோட்டம் சரியாக இருக்குமா?", "aEn": "It is a close guide to the final result, refined further with a physical mock-up in your mouth.", "aTa": "மிக நெருக்கமாக இருக்கும்; வாயில் சோதனை மூலம் மேலும் சரிசெய்யப்படும்."}, {"qEn": "Does it cost extra?", "qTa": "கூடுதல் கட்டணமா?", "aEn": "Design planning is included when you proceed with the smile treatment.", "aTa": "சிகிச்சை தொடர்ந்தால் வடிவமைப்பு சேர்க்கப்பட்டுள்ளது."}]'::jsonb,70,true),
('cbct-imaging','Scan','CBCT Imaging','CBCT படமெடுப்பு','3D cone beam CT, RVG dental X-ray','3D CBCT, RVG டென்டல் எக்ஸ்-ரே','Cone beam CT gives a three-dimensional view of bone, nerves and sinuses. It is essential for implant planning, impacted teeth and complex root canal anatomy.','CBCT எலும்பு, நரம்பு மற்றும் சைனஸ்களை முப்பரிமாணமாக காட்டுகிறது. இம்ப்ளான்ட் திட்டமிடல் மற்றும் சிக்கலான சிகிச்சைகளுக்கு அவசியம்.','["3D cone beam scan", "Low-dose RVG X-ray", "Reports shared to your patient portal", "Used for implant & surgical planning"]'::jsonb,'["3D CBCT ஸ்கேன்", "குறைந்த அளவு RVG", "நோயாளி போர்ட்டலில் அறிக்கை", "அறுவை சிகிச்சை திட்டமிடல்"]'::jsonb,'[{"qEn": "Is CBCT radiation safe?", "qTa": "கதிர்வீச்சு பாதுகாப்பானதா?", "aEn": "A dental CBCT uses a small fraction of a medical CT dose and is taken only when it changes treatment.", "aTa": "மருத்துவ CT-யை விட மிகக் குறைவு; தேவைப்பட்டால் மட்டுமே எடுக்கப்படும்."}, {"qEn": "How long does the scan take?", "qTa": "எவ்வளவு நேரம்?", "aEn": "The scan itself takes under a minute and you stay seated or standing still.", "aTa": "ஒரு நிமிடத்திற்கும் குறைவு."}, {"qEn": "Can I get a copy?", "qTa": "நகல் கிடைக்குமா?", "aEn": "Yes, scans and reports are uploaded to your patient portal.", "aTa": "ஆம், நோயாளி போர்ட்டலில் பதிவேற்றப்படும்."}]'::jsonb,80,true),
('oral-surgery','Scissors','Oral Surgery','வாய் அறுவை சிகிச்சை','Wisdom teeth extraction, minor oral surgery','ஞான பல் அகற்றல், சிறு அறுவை சிகிச்சை','Impacted wisdom teeth, retained roots, cysts and minor jaw procedures are handled in-clinic under local anaesthesia with careful post-operative care instructions.','ஞான பற்கள், மீதமுள்ள வேர்கள், நீர்க்கட்டிகள் ஆகியவை கிளினிக்கிலேயே மரத்துப்போகும் மருந்துடன் சிகிச்சை அளிக்கப்படுகிறது.','["Impacted wisdom tooth removal", "Surgical extractions", "Cyst & lesion removal", "Detailed aftercare support"]'::jsonb,'["ஞான பல் அகற்றல்", "அறுவை சிகிச்சை மூலம் பல் எடுத்தல்", "நீர்க்கட்டி நீக்கம்", "பின் பராமரிப்பு ஆலோசனை"]'::jsonb,'[{"qEn": "How long is recovery after extraction?", "qTa": "குணமாக எவ்வளவு நாட்கள்?", "aEn": "Swelling settles in 2-3 days and most people return to normal routine the next day.", "aTa": "வீக்கம் 2-3 நாட்களில் குறையும்; அடுத்த நாளே வழக்கமான வேலைக்கு திரும்பலாம்."}, {"qEn": "What should I eat afterwards?", "qTa": "என்ன சாப்பிடலாம்?", "aEn": "Cool, soft food for 24 hours. Avoid hot drinks, straws, spitting and smoking.", "aTa": "24 மணி நேரம் குளிர்ந்த மென்மையான உணவு; சூடான பானம், ஸ்ட்ரா, புகைப்பிடித்தல் தவிர்க்கவும்."}, {"qEn": "Do all wisdom teeth need removal?", "qTa": "எல்லா ஞான பற்களும் எடுக்க வேண்டுமா?", "aEn": "No. Only those causing pain, decay, gum infection or crowding are removed.", "aTa": "இல்லை. பிரச்சனை ஏற்படுத்துபவை மட்டுமே."}]'::jsonb,90,true),
('pediatric-dentistry','Baby','Pediatric Dentistry','குழந்தை பல் மருத்துவம்','Child dentistry, anterior teeth, space maintainers','குழந்தைகளுக்கு ஏற்ற மென்மையான சிகிச்சை','Gentle, child-friendly care covering fluoride application, pit and fissure sealants, milk-tooth fillings, pulpectomy and space maintainers after early tooth loss.','குழந்தைகளுக்கு ஏற்ற மென்மையான சிகிச்சை: புளோரைடு, சீலண்ட், பால் பல் நிரப்புதல், ஸ்பேஸ் மெயின்டெய்னர்.','["Fluoride & sealants", "Milk tooth fillings", "Habit-breaking appliances", "Behaviour-friendly approach"]'::jsonb,'["புளோரைடு & சீலண்ட்", "பால் பல் நிரப்புதல்", "பழக்க திருத்தும் கருவிகள்", "குழந்தை நட்பு அணுகுமுறை"]'::jsonb,'[{"qEn": "When should a child first see a dentist?", "qTa": "எப்போது முதல் வருகை?", "aEn": "By the first birthday, or within six months of the first tooth appearing.", "aTa": "முதல் பிறந்தநாளுக்குள் அல்லது முதல் பல் வந்த ஆறு மாதங்களுக்குள்."}, {"qEn": "Do milk teeth with decay need treatment?", "qTa": "பால் பல்லுக்கு சிகிச்சை தேவையா?", "aEn": "Yes. Untreated decay causes pain, infection and can damage the permanent tooth developing below.", "aTa": "ஆம். சிகிச்சை இல்லாவிட்டால் நிரந்தர பல்லும் பாதிக்கப்படும்."}]'::jsonb,100,true),
('dentures','CircleDot','Dentures','செயற்கை பற்கள்','Artificial teeth, full mouth rehabilitation','செயற்கை பற்கள், முழு வாய் மறுவாழ்வு','Complete and partial dentures restore chewing and facial support. Implant-supported overdentures are available when a conventional denture feels loose.','முழு மற்றும் பகுதி செயற்கை பற்கள் மெல்லும் திறனை மீட்கின்றன. தளர்வாக இருந்தால் இம்ப்ளான்ட் ஆதரவு பற்கள் கிடைக்கும்.','["Complete & partial dentures", "Flexible / BPS options", "Implant-supported overdentures", "Repairs & relining"]'::jsonb,'["முழு & பகுதி பற்கள்", "நெகிழ்வான வகைகள்", "இம்ப்ளான்ட் ஆதரவு", "பழுது & ரிலைனிங்"]'::jsonb,'[{"qEn": "How long to get used to dentures?", "qTa": "பழக எவ்வளவு நாள்?", "aEn": "Two to four weeks for speech and chewing to feel natural.", "aTa": "இரண்டு முதல் நான்கு வாரங்கள்."}, {"qEn": "Can dentures be made in a week?", "qTa": "ஒரு வாரத்தில் கிடைக்குமா?", "aEn": "Yes, most conventional dentures are delivered within 5-7 days across a few visits.", "aTa": "ஆம், பொதுவாக 5-7 நாட்களில்."}]'::jsonb,110,true),
('tooth-jewellery','Gem','Tooth Jewellery','பல் நகை','Cosmetic tooth jewellery and accessories','அழகு பல் நகைகள்','A small crystal is bonded to the enamel surface with no drilling. It is painless, fully reversible and takes about fifteen minutes.','சிறிய படிகம் பல் மேற்பரப்பில் ஒட்டப்படுகிறது; துளையிடல் இல்லை, வலியில்லை, 15 நிமிடங்களில் முடியும்.','["No drilling, no pain", "Removable any time", "15-minute appointment", "Wide crystal selection"]'::jsonb,'["துளையிடல் இல்லை", "எப்போது வேண்டுமானாலும் நீக்கலாம்", "15 நிமிட சிகிச்சை", "பல வகை படிகங்கள்"]'::jsonb,'[{"qEn": "Does it harm the tooth?", "qTa": "பல்லுக்கு பாதிப்பா?", "aEn": "No. It is bonded like an orthodontic bracket and leaves the enamel intact when removed.", "aTa": "இல்லை. நீக்கிய பின்னும் பல் பாதுகாப்பாக இருக்கும்."}, {"qEn": "How long does it stay?", "qTa": "எவ்வளவு காலம் இருக்கும்?", "aEn": "Typically six months to a year, sometimes longer.", "aTa": "பொதுவாக ஆறு மாதம் முதல் ஒரு வருடம்."}]'::jsonb,120,true),
('oral-cancer-screening','Search','Oral Cancer Screening','வாய் புற்றுநோய் பரிசோதனை','Oral cancer screening and surgical intervention','வாய் புற்றுநோய் பரிசோதனை மற்றும் அறுவை சிகிச்சை','A quick, painless examination of the cheeks, tongue, palate and throat for early signs of pre-cancerous change — especially important for tobacco and areca nut users.','கன்னம், நாக்கு, அண்ணம் மற்றும் தொண்டையை விரைவாக, வலியின்றி பரிசோதிப்பது. புகையிலை/பாக்கு பயன்படுத்துபவர்களுக்கு மிக முக்கியம்.','["Painless 5-minute screening", "Tobacco cessation counselling", "Biopsy & referral when needed", "Regular follow-up"]'::jsonb,'["5 நிமிட பரிசோதனை", "புகையிலை நிறுத்த ஆலோசனை", "தேவைப்பட்டால் பயாப்ஸி", "தொடர் கண்காணிப்பு"]'::jsonb,'[{"qEn": "Who should be screened?", "qTa": "யார் பரிசோதிக்க வேண்டும்?", "aEn": "Anyone using tobacco, areca nut or alcohol, and anyone with a mouth ulcer lasting over two weeks.", "aTa": "புகையிலை, பாக்கு, மது பயன்படுத்துபவர்கள்; இரண்டு வாரங்களுக்கு மேல் புண் இருந்தால்."}, {"qEn": "Is a white or red patch serious?", "qTa": "வெள்ளை/சிவப்பு புள்ளி ஆபத்தானதா?", "aEn": "It needs assessment. Many are harmless, but persistent patches must be examined and sometimes biopsied.", "aTa": "பரிசோதனை தேவை. பல பாதிப்பில்லாதவை, ஆனால் நீடித்தால் ஆய்வு அவசியம்."}]'::jsonb,130,true),
('gum-surgery','Syringe','Gum Surgery','ஈறு அறுவை சிகிச்சை','Post and core, filling and restoration','ஈறு சிகிச்சை, நிரப்புதல் மற்றும் மறுசீரமைப்பு','Treatment for bleeding, receding or swollen gums — from deep cleaning and curettage to flap surgery and gum grafting for advanced periodontitis.','இரத்தம் வடியும், பின்வாங்கும் அல்லது வீங்கிய ஈறுகளுக்கு ஆழ்ந்த சுத்தம் முதல் ஃபிளாப் அறுவை சிகிச்சை வரை.','["Deep cleaning & root planing", "Flap surgery", "Gum grafting & depigmentation", "Maintenance programme"]'::jsonb,'["ஆழ்ந்த சுத்தம்", "ஃபிளாப் அறுவை சிகிச்சை", "ஈறு ஒட்டுதல்", "தொடர் பராமரிப்பு"]'::jsonb,'[{"qEn": "Why do my gums bleed?", "qTa": "ஈறு ஏன் இரத்தம் வடிகிறது?", "aEn": "Almost always from plaque and tartar causing gingivitis. It is reversible if treated early.", "aTa": "பெரும்பாலும் படிவுகளால் ஏற்படும் ஈறு அழற்சி; ஆரம்பத்திலேயே சரிசெய்யலாம்."}, {"qEn": "Can loose teeth be saved?", "qTa": "தளர்ந்த பல்லை காப்பாற்ற முடியுமா?", "aEn": "Often yes, with gum treatment and splinting, if enough bone support remains.", "aTa": "எலும்பு ஆதரவு இருந்தால் பெரும்பாலும் முடியும்."}]'::jsonb,140,true),
('geriatric-dentistry','Eye','Geriatric Dentistry','முதியோர் பல் மருத்துவம்','Specialized dental care for elderly patients','முதியோருக்கான சிறப்பு பல் சிகிச்சை','Care designed around older patients: dry mouth management, denture comfort, root caries, and coordination with medical conditions and blood thinners. Home visits are available through Smile on the Go.','முதியோருக்கான சிறப்பு பராமரிப்பு: வறண்ட வாய், செயற்கை பல் வசதி, வேர் சொத்தை மற்றும் மருத்துவ நிலைகளுடன் ஒருங்கிணைப்பு. வீட்டு வருகையும் உண்டு.','["Home visits available", "Denture comfort & relining", "Dry mouth management", "Safe care with medical conditions"]'::jsonb,'["வீட்டு வருகை", "செயற்கை பல் வசதி", "வறண்ட வாய் சிகிச்சை", "மருத்துவ நிலைகளுக்கு ஏற்ற பாதுகாப்பு"]'::jsonb,'[{"qEn": "Do you visit patients at home?", "qTa": "வீட்டிற்கு வருவீர்களா?", "aEn": "Yes. Our Smile on the Go service brings check-ups and simple treatment to patients with limited mobility.", "aTa": "ஆம். Smile on the Go சேவை மூலம் வீட்டிலேயே சிகிச்சை."}, {"qEn": "Is treatment safe on blood thinners?", "qTa": "இரத்த மெல்லிய மருந்து எடுத்தால் பாதுகாப்பானதா?", "aEn": "Usually yes, with planning. Bring your medication list and we coordinate with your physician.", "aTa": "பொதுவாக ஆம். மருந்து பட்டியலை கொண்டு வாருங்கள்."}]'::jsonb,150,true)
